@Override
public boolean equals(Object o) {
    if (o == null || !(o instanceof NameStateWithPattern)) {
        return false;
    }
    NameStateWithPattern otherNameStateWithPattern = (NameStateWithPattern) o;
    return nameState.equals(otherNameStateWithPattern.nameState) && pattern.equals(otherNameStateWithPattern.pattern);
}
